// Confirms the incoming item is a well-formed API Request Contract
// (docs/contracts/api-request-contract.md) before any HTTP-specific
// validation or execution happens. This is the only node that validates
// the contract's envelope shape - later nodes trust it and only validate
// their own narrow concern.
const STAGE = 'http_executor';
const WORKFLOW_VERSION = '1.0';

function errorPayload(code, message, details) {
  return {
    status: 'ERROR',
    stage: STAGE,
    code,
    message,
    details: details || {},
    timestamp: new Date().toISOString(),
    workflow_version: WORKFLOW_VERSION
  };
}

const item = $input.item.json;

// ERROR payloads produced upstream (API Request Builder) are not request
// contracts and must not be re-validated as one - pass them through
// unchanged, same convention as 01-ingestion and 02-api-request-builder.
if (item && item.status === 'ERROR') {
  return { json: item };
}

if (typeof item !== 'object' || item === null || Array.isArray(item)) {
  return { json: errorPayload(
    'INVALID_API_REQUEST_CONTRACT',
    'API Request Contract must be a JSON object',
    { received_type: Array.isArray(item) ? 'array' : typeof item }
  ) };
}

const requiredFields = [
  'workflow_version', 'contract_version', 'request_id', 'method',
  'base_url', 'path', 'url', 'headers', 'query', 'authentication',
  'timeout', 'expected', 'test_case', 'metadata'
];
const missingFields = requiredFields.filter((field) => item[field] === undefined);

if (missingFields.length > 0) {
  return { json: errorPayload(
    'INVALID_API_REQUEST_CONTRACT',
    `API Request Contract is missing required field(s): ${missingFields.join(', ')}`,
    { missing_fields: missingFields, request_id: item.request_id || null }
  ) };
}

if (typeof item.headers !== 'object' || item.headers === null || Array.isArray(item.headers)) {
  return { json: errorPayload(
    'INVALID_API_REQUEST_CONTRACT',
    'API Request Contract headers must be a JSON object',
    { request_id: item.request_id }
  ) };
}

if (typeof item.query !== 'object' || item.query === null || Array.isArray(item.query)) {
  return { json: errorPayload(
    'INVALID_API_REQUEST_CONTRACT',
    'API Request Contract query must be a JSON object',
    { request_id: item.request_id }
  ) };
}

if (typeof item.authentication !== 'object' || item.authentication === null || !item.authentication.type) {
  return { json: errorPayload(
    'INVALID_API_REQUEST_CONTRACT',
    'API Request Contract authentication must be an object with a type',
    { request_id: item.request_id }
  ) };
}

if (typeof item.timeout !== 'number' || item.timeout <= 0) {
  return { json: errorPayload(
    'INVALID_API_REQUEST_CONTRACT',
    `API Request Contract timeout must be a positive number, received "${item.timeout}"`,
    { request_id: item.request_id, timeout: item.timeout }
  ) };
}

return { json: item };

// Re-validates method and URL independently of the API Request Builder -
// defense in depth, this workflow must not trust a malformed or
// hand-crafted contract just because it has the right shape. No AI, no
// inference - fixed whitelist and native URL parsing only.
const STAGE = 'http_executor';
const WORKFLOW_VERSION = '1.0';
const SUPPORTED_METHODS = ['GET', 'POST', 'PUT', 'PATCH', 'DELETE'];

function errorPayload(code, message, details) {
  return {
    status: 'ERROR',
    stage: STAGE,
    code,
    message,
    details: details || {},
    timestamp: new Date().toISOString(),
    workflow_version: WORKFLOW_VERSION
  };
}

const item = $input.item.json;

if (item.status === 'ERROR') {
  return { json: item };
}

const method = String(item.method).trim().toUpperCase();

if (!SUPPORTED_METHODS.includes(method)) {
  return { json: errorPayload(
    'UNSUPPORTED_HTTP_METHOD',
    `HTTP method "${method}" is not supported. Supported methods: ${SUPPORTED_METHODS.join(', ')}`,
    { request_id: item.request_id, method }
  ) };
}

let parsedUrl;
try {
  parsedUrl = new URL(item.url);
} catch (err) {
  return { json: errorPayload(
    'INVALID_URL',
    `"${item.url}" is not a valid URL`,
    { request_id: item.request_id, url: item.url }
  ) };
}

if (parsedUrl.protocol !== 'http:' && parsedUrl.protocol !== 'https:') {
  return { json: errorPayload(
    'INVALID_URL',
    `URL "${item.url}" must use http or https, received "${parsedUrl.protocol}"`,
    { request_id: item.request_id, url: item.url }
  ) };
}

return { json: { ...item, __method: method, __url: item.url } };

// Merges request headers with a resolved credential for bearer/api_key
// auth strategies, read from this workflow's own environment variables -
// never from the API Request Contract, which per ADR 002 / the API
// Request Contract's Authentication structure only ever carries a
// strategy marker, never a real secret. This is the "resolved_by:
// http_executor" step that contract document promises. Also resolves
// query/body/timeout into the working fields the HTTP Request node reads.
const STAGE = 'http_executor';
const WORKFLOW_VERSION = '1.0';
const SUPPORTED_AUTH_TYPES = ['none', 'bearer', 'api_key'];

function errorPayload(code, message, details) {
  return {
    status: 'ERROR',
    stage: STAGE,
    code,
    message,
    details: details || {},
    timestamp: new Date().toISOString(),
    workflow_version: WORKFLOW_VERSION
  };
}

const item = $input.item.json;

if (item.status === 'ERROR') {
  return { json: item };
}

const authType = item.authentication && item.authentication.type
  ? String(item.authentication.type).trim().toLowerCase()
  : 'none';

if (!SUPPORTED_AUTH_TYPES.includes(authType)) {
  return { json: errorPayload(
    'UNSUPPORTED_AUTHENTICATION',
    `Authentication type "${authType}" is not supported. Supported types: ${SUPPORTED_AUTH_TYPES.join(', ')}`,
    { request_id: item.request_id, auth_type: authType }
  ) };
}

const headers = { ...item.headers };

if (authType === 'bearer') {
  const token = $env.API_AUTH_BEARER_TOKEN;
  if (!token) {
    return { json: errorPayload(
      'MISSING_CREDENTIALS',
      'Authentication type "bearer" requires API_AUTH_BEARER_TOKEN to be set',
      { request_id: item.request_id, auth_type: authType, required_env: 'API_AUTH_BEARER_TOKEN' }
    ) };
  }
  headers.Authorization = `Bearer ${token}`;
}

if (authType === 'api_key') {
  const headerName = $env.API_AUTH_API_KEY_HEADER || 'X-API-Key';
  const value = $env.API_AUTH_API_KEY_VALUE;
  if (!value) {
    return { json: errorPayload(
      'MISSING_CREDENTIALS',
      'Authentication type "api_key" requires API_AUTH_API_KEY_VALUE to be set',
      { request_id: item.request_id, auth_type: authType, required_env: 'API_AUTH_API_KEY_VALUE' }
    ) };
  }
  headers[headerName] = value;
}

return { json: {
  ...item,
  __headers: headers,
  __query: item.query || {},
  __body: item.body === undefined ? null : item.body,
  __timeout: item.timeout,
  __sent_at: new Date().toISOString(),
  __start_ms: Date.now()
} };

// Final assembly for a request that actually executed (any status code,
// including 4xx/5xx - the HTTP Request node is configured with
// neverError so those are not thrown as node errors). Builds the HTTP
// Response Contract (docs/contracts/http-response-contract.md). This
// workflow never compares status_code against `expected` or decides
// PASS/FAIL - that is the Decision Agent's job (docs/architecture/
// milestone-1.md section 5), not this one's.
const CONTRACT_VERSION = '1.0';
const EXECUTOR_WORKFLOW_VERSION = '1.0';

function uuidv4() {
  return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, (c) => {
    const r = (Math.random() * 16) | 0;
    const v = c === 'x' ? r : (r & 0x3) | 0x8;
    return v.toString(16);
  });
}

const requestItem = $('Apply Authentication').item.json;
const httpResult = $input.item.json;
const receivedAt = new Date().toISOString();

const responseContract = {
  workflow_version: EXECUTOR_WORKFLOW_VERSION,
  contract_version: CONTRACT_VERSION,
  request_id: requestItem.request_id,
  response_id: uuidv4(),
  status_code: httpResult.statusCode,
  status_text: httpResult.statusMessage || null,
  headers: httpResult.headers || {},
  body: httpResult.body !== undefined ? httpResult.body : null,
  latency_ms: Date.now() - requestItem.__start_ms,
  timestamps: {
    sent_at: requestItem.__sent_at,
    received_at: receivedAt
  },
  request: {
    method: requestItem.__method,
    url: requestItem.__url
  },
  expected: requestItem.expected,
  test_case: requestItem.test_case,
  metadata: {
    created_at: receivedAt,
    source_workflow: '03-http-executor',
    next_workflow: '04-response-normalizer'
  }
};

return { json: responseContract };

// Handles the HTTP Request node's error output - a genuine execution
// failure (DNS/connection/timeout/malformed request), as opposed to a
// non-2xx HTTP status, which is captured as a normal response instead
// because the node is configured with neverError. Maps n8n's raw error
// to one of this workflow's stable error codes on a best-effort basis;
// anything unrecognized falls back to NETWORK_ERROR rather than being
// dropped. Different HTTP clients (axios, undici/fetch) surface the same
// underlying failure differently - some put ECONNREFUSED/ETIMEDOUT in
// `code`, some in `message`, some nest it under `cause` - so every field
// that might carry the real reason is folded into one string before
// matching, rather than trusting a single field to be present.
const STAGE = 'http_executor';
const WORKFLOW_VERSION = '1.0';

const requestItem = $('Apply Authentication').item.json;
const rawError = $input.item.json;

const parts = [
  rawError.code,
  rawError.error,
  rawError.message,
  rawError.cause && rawError.cause.code,
  rawError.cause && rawError.cause.message,
  rawError.name
].filter(Boolean);
const message = parts.length > 0 ? parts.join(' | ') : JSON.stringify(rawError);

function codeFor(msg) {
  const lower = msg.toLowerCase();
  if (lower.includes('econnrefused')) return 'CONNECTION_REFUSED';
  if (lower.includes('etimedout') || lower.includes('econnaborted') || lower.includes('timeout') || lower.includes('abort')) return 'TIMEOUT_ERROR';
  if (lower.includes('enotfound') || lower.includes('eai_again')) return 'DNS_RESOLUTION_FAILED';
  if (lower.includes('invalid url') || lower.includes('err_invalid_url')) return 'INVALID_URL';
  return 'NETWORK_ERROR';
}

return { json: {
  status: 'ERROR',
  stage: STAGE,
  code: codeFor(message),
  message: `HTTP request for request_id "${requestItem.request_id}" failed: ${message}`,
  details: {
    request_id: requestItem.request_id,
    method: requestItem.__method,
    url: requestItem.__url
  },
  timestamp: new Date().toISOString(),
  workflow_version: WORKFLOW_VERSION
} };
